#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using NUnit.Framework;using UnityEditor;using UnityEngine;
namespace HorrorGame.Tests{
 [Category("Lockpick")]public sealed class LockpickTests{
 [Serializable]class Row{public string difficulty;public int samples,breaks,wrongAngle10SecondsBreaks;public float meanSeconds,minSeconds,maxSeconds;}
 [Serializable]class Evidence{public Row[] rows;public long warm10000StepsBytes,allocationProbeBytes;public bool allocationApiSupported;public string scope;}
 LockpickConfig c;const string W="C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/work/Lockpick20261101/";
 [SetUp]public void Setup(){c=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<LockpickConfig>("Assets/HorrorGameplay/Data/Lockpick/LockpickConfig.asset"));Assert.That(c,Is.Not.Null);}
 [TearDown]public void Cleanup(){UnityEngine.Object.DestroyImmediate(c);}
 [TestCase(LockDifficulty.Easy)][TestCase(LockDifficulty.Medium)][TestCase(LockDifficulty.Hard)]public void ConsecutivePinsFinishWithoutBreaks(LockDifficulty d){var a=new LockpickAttempt(c,d,"test");var result=LockpickResult.None;int clicks=0;for(int i=0;i<2000&&result!=LockpickResult.Complete;i++){result=a.Step(.05f,a.TargetAngle,true,false,false,0);if(result==LockpickResult.PinSet)clicks++;}Assert.That(result,Is.EqualTo(LockpickResult.Complete));Assert.That(clicks,Is.EqualTo((int)d-1));Assert.That(a.CompletedPins,Is.EqualTo((int)d));Assert.That(a.Step(.05f,0,true,false,false,0),Is.EqualTo(LockpickResult.None));}
 [Test]public void BrokenActivePinRetainsEarlierPinsAndSeedAcrossReload(){var a=new LockpickAttempt(c,LockDifficulty.Medium,"same-id");while(a.CompletedPins==0)a.Step(.1f,a.TargetAngle,true,false,false,0);float target=a.TargetAngle;var result=LockpickResult.None;for(int i=0;i<1000&&result!=LockpickResult.Broken;i++)result=a.Step(.1f,target>90?0:180,true,false,false,0);Assert.That(result,Is.EqualTo(LockpickResult.Broken));Assert.That(a.CompletedPins,Is.EqualTo(1));Assert.That(a.Progress,Is.Zero);Assert.That(new LockpickAttempt(c,LockDifficulty.Medium,"same-id",1).TargetAngle,Is.EqualTo(target));}
 [Test]public void AssistanceAndThreeBreaksIncreaseToleranceAndLowerStress(){var a=new LockpickAttempt(c,LockDifficulty.Easy,"test");var b=new LockpickAttempt(c,LockDifficulty.Easy,"test");Assert.That(a.EffectiveTolerance(true,0),Is.EqualTo(22.5f));Assert.That(a.EffectiveTolerance(false,3),Is.EqualTo(20.7f).Within(.001f));float wrong=a.TargetAngle>90?0:180;a.Step(.1f,wrong,true,false,false,0);b.Step(.1f,wrong,true,true,false,0);Assert.That(b.Stress,Is.EqualTo(a.Stress*.45f).Within(.00001f));float stress=a.Stress;a.Step(.1f,wrong,false,false,false,0);Assert.That(a.Stress,Is.LessThan(stress));}
 [TestCase(LockDifficulty.Easy,9)][TestCase(LockDifficulty.Medium,18)][TestCase(LockDifficulty.Hard,27)]public void AutomaticRequiresContinuousHold(LockDifficulty d,float seconds){var a=new LockpickAttempt(c,d,"auto");for(int i=0;i<10;i++)a.Step(.1f,0,true,false,true,0);a.Step(.1f,0,false,false,true,0);var r=LockpickResult.None;float elapsed=0;while(r!=LockpickResult.Complete&&elapsed<seconds+1){r=a.Step(.05f,0,true,false,true,0);elapsed+=.05f;}Assert.That(elapsed,Is.InRange(seconds-.01f,seconds+.11f));Assert.That(a.Stress,Is.Zero);}
 [Test]public void InvalidDeltaAndLegacyStateDoNotCreateProgress(){var a=new LockpickAttempt(c,LockDifficulty.Easy,"test");foreach(float dt in new[]{0,-1,float.NaN,float.PositiveInfinity})Assert.That(a.Step(dt,0,true,false,false,0),Is.EqualTo(LockpickResult.None));Assert.That(a.Elapsed,Is.Zero);Assert.That(JsonUtility.FromJson<SaveData>("{\"version\":2}").lockpick.initialized,Is.False);Assert.That(new LockpickState{version=9}.Valid,Is.False);Assert.That(new LockpickState{initialized=true,count=1}.Valid,Is.False);}
 [Test]public void InstalledDialogueAndProposalsSurviveNativeAssetReload(){Assert.That(c.dialogue.lines.Length,Is.EqualTo(63));Assert.That(c.dialogue.lines.Select(l=>l.id).Distinct().Count(),Is.EqualTo(63));Assert.That(c.dialogue.lines.Count(l=>l.id.StartsWith("wp_opt_lockpick_")),Is.EqualTo(44));Assert.That(c.dialogue.lines.All(l=>!string.IsNullOrWhiteSpace(l.text)),Is.True);Assert.That(AssetDatabase.FindAssets("t:LockpickNoteProposal").Length,Is.EqualTo(5));foreach(var guid in AssetDatabase.FindAssets("t:LockpickNoteProposal")){var note=AssetDatabase.LoadAssetAtPath<LockpickNoteProposal>(AssetDatabase.GUIDToAssetPath(guid));Assert.That(note.status,Does.Contain("APROVAR"));}Assert.That(c.scrape.clips.All(x=>x),Is.True);}
 [Test]public void MainStoryNeverReferencesLockpickAndSourceDoesNotScanInUpdate(){var book=AssetDatabase.LoadAssetAtPath<StoryBook>("Assets/HorrorGameplay/Data/BeforeDemolition/BeforeDemolitionStory.asset");if(!book){book=AssetDatabase.FindAssets("t:StoryBook").Select(g=>AssetDatabase.LoadAssetAtPath<StoryBook>(AssetDatabase.GUIDToAssetPath(g))).First(b=>BeforeDemolitionCampaign.Is(b));}Assert.That(JsonUtility.ToJson(book).ToLowerInvariant(),Does.Not.Contain("lockpick"));foreach(string file in new[]{"LockpickSystem.cs","LockpickView.cs"})Assert.That(File.ReadAllText("Assets/HorrorGameplay/Scripts/Lockpick/"+file),Does.Not.Contain("FindObject"));}
 [Test]public void WrapperCannotStealAKeyedDoorOrItsPrompt(){var go=new GameObject("Keyed main door");go.SetActive(false);try{var door=go.AddComponent<InteractiveDoor>();door.requiredKey="main.key";door.locked=true;var wrapper=go.AddComponent<LockableDoor>();wrapper.door=door;door.optionalLock=wrapper;Assert.That(wrapper.IsOptional,Is.False);Assert.That(wrapper.Handles,Is.False);Assert.That(wrapper.CanInteract(null),Is.False);Assert.That(door.Prompt(null),Does.Not.Contain("Arrombar"));wrapper.kind=LockKind.Key;Assert.That(wrapper.Handles,Is.False);}finally{UnityEngine.Object.DestroyImmediate(go);}}
 [Test]public void CalibratedBotsAndWarmStepAllocationEvidence(){var rows=new List<Row>();foreach(LockDifficulty d in Enum.GetValues(typeof(LockDifficulty))){float total=0,min=float.MaxValue,max=0;int breaks=0;for(int sample=0;sample<30;sample++){var a=new LockpickAttempt(c,d,"bot."+sample);float search=0;var result=LockpickResult.None;int last=0;while(result!=LockpickResult.Complete&&a.Elapsed<100){if(a.CompletedPins!=last){search=0;last=a.CompletedPins;}float delay=(int)d==1?3:(int)d==2?5:7;search+=.05f;bool hold=search>=delay;float angle=hold?a.TargetAngle:90;result=a.Step(.05f,angle,hold,false,false,breaks);if(result==LockpickResult.Broken)breaks++;}total+=a.Elapsed;min=Math.Min(min,a.Elapsed);max=Math.Max(max,a.Elapsed);}var noisy=new LockpickAttempt(c,d,"noisy");int fails=0;for(int i=0;i<200;i++)if(noisy.Step(.05f,noisy.TargetAngle>90?0:180,true,false,false,fails)==LockpickResult.Broken)fails++;rows.Add(new Row{difficulty=d.ToString(),samples=30,meanSeconds=total/30,minSeconds=min,maxSeconds=max,breaks=breaks,wrongAngle10SecondsBreaks=fails});Assert.That(total/30,Is.InRange((int)d==1?8:(int)d==2?15:25,(int)d==1?15:(int)d==2?30:50));}var warm=new LockpickAttempt(c,LockDifficulty.Hard,"allocation");for(int i=0;i<100;i++)warm.Step(.01f,0,false,false,false,0);long before=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<10000;i++)warm.Step(.01f,0,false,false,false,0);long bytes=GC.GetAllocatedBytesForCurrentThread()-before;long p0=GC.GetAllocatedBytesForCurrentThread();var probe=new byte[4096];long probeBytes=GC.GetAllocatedBytesForCurrentThread()-p0;GC.KeepAlive(probe);File.WriteAllText(W+"calibration.json",JsonUtility.ToJson(new Evidence{rows=rows.ToArray(),warm10000StepsBytes=bytes,allocationProbeBytes=probeBytes,allocationApiSupported=probeBytes>=4096,scope="Deterministic bot: searches 3/5/7s per pin, then perfect tension. Not a human feel test; no GPU/UI or save I/O. Zero bytes is NOT meaningful unless positive-control probe succeeds."},true));if(probeBytes>=4096)Assert.That(bytes,Is.Zero);}
 }
}
#endif

